package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.world.phys.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.ChunkPos;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.client.event.*;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.minecraftforge.api.distmarker.Dist.CLIENT)
public final class Sk01Client {
 private record Near(Visual visual,double distance){}
 private static Iterator<Visual> scan;private static Vec3 scanOrigin;
 private static final PriorityQueue<Near> nearest=new PriorityQueue<>(Comparator.comparingDouble(Near::distance).reversed());
 private record Visual(Sk01Entry entry,AABB box){}
 private static final class Chunk {long revision=-1;final Map<UUID,Visual>entries=new HashMap<>();}
 private static final Map<UUID,Set<Visual>>SOURCES=new HashMap<>();
 private static final Map<Long,Chunk>CHUNKS=new HashMap<>();private static final ArrayList<Visual>VISIBLE=new ArrayList<>();private static ClientLevel world;private static Object connection;private static boolean dirty=true;private static int ticks;
 public static int drawn,detailDrawn,lodDrawn;public static long lastRenderNanos;
 private static void ensure(){var m=Minecraft.getInstance();if(world!=m.level||connection!=m.getConnection()){CHUNKS.clear();SOURCES.clear();VISIBLE.clear();scan=null;nearest.clear();dirty=true;world=m.level;connection=m.getConnection();}}
 private static void unlink(Visual v){if(v==null)return;var set=SOURCES.get(v.entry.source());if(set!=null){set.remove(v);if(set.isEmpty())SOURCES.remove(v.entry.source());}}
 private static void drop(long key){var c=CHUNKS.remove(key);if(c!=null)for(var v:c.entries.values())unlink(v);}
 public static void apply(Sk01Packet p){ensure();if(world==null||!world.dimension().location().equals(p.dimension()))return;if(p.unload()){drop(p.chunk());dirty=true;return;}var c=CHUNKS.computeIfAbsent(p.chunk(),k->new Chunk());if(p.revision()<c.revision&&!p.reset())return;if(p.reset()){for(var v:c.entries.values())unlink(v);c.entries.clear();}c.revision=p.revision();for(var change:p.changes()){unlink(c.entries.remove(change.id()));if(change.entry()!=null){var v=new Visual(change.entry(),change.entry().bounds());c.entries.put(change.id(),v);SOURCES.computeIfAbsent(v.entry.source(),k->new HashSet<>()).add(v);}}dirty=true;}
 /** Preserve the normal death animation, then hide only its confirmed dead visual.
  * Loot, XP, boss death logic and live respawned players remain untouched. */
 @SubscribeEvent public static void original(RenderLivingEvent.Pre<?,?> event){ensure();var e=event.getEntity();if(world==null||!Sk01Config.ENABLED.get()||!e.isDeadOrDying()||e.deathTime<20)return;var list=SOURCES.get(e.getUUID());if(list!=null)for(var v:list)if(!v.entry.pending()&&world.getGameTime()-v.entry.created()>=20){event.setCanceled(true);return;}}
 public static int count(){ensure();return CHUNKS.values().stream().mapToInt(c->c.entries.size()).sum();}
 @SubscribeEvent public static void tick(net.minecraftforge.event.TickEvent.ClientTickEvent event){if(event.phase!=net.minecraftforge.event.TickEvent.Phase.END)return;ensure();if(world==null)return;if(!Sk01Config.ENABLED.get()){VISIBLE.clear();scan=null;nearest.clear();return;}int limit=Math.min(512,Sk01ClientConfig.MAX.get());if(limit==0){VISIBLE.clear();scan=null;nearest.clear();return;}ticks++;if(dirty||scan==null&&ticks%10==0){dirty=false;nearest.clear();scanOrigin=Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();scan=CHUNKS.values().stream().flatMap(c->c.entries.values().stream()).iterator();}if(scan==null)return;long deadline=System.nanoTime()+600_000;double range=Sk01ClientConfig.DISTANCE.get();int units=0;while(scan.hasNext()&&units++<512&&System.nanoTime()<deadline){var v=scan.next();if(v.entry.pending())continue;double d=v.entry.position().distanceToSqr(scanOrigin);if(d>range*range)continue;if(nearest.size()<limit)nearest.add(new Near(v,d));else if(d<nearest.peek().distance){nearest.remove();nearest.add(new Near(v,d));}}VISIBLE.clear();nearest.stream().sorted(Comparator.comparingDouble(Near::distance)).forEach(n->VISIBLE.add(n.visual));if(!scan.hasNext())scan=null;}

 @SubscribeEvent public static void unload(net.minecraftforge.event.level.ChunkEvent.Unload e){if(e.getLevel()==world){drop(e.getChunk().getPos().toLong());dirty=true;}}
 @SubscribeEvent public static void render(RenderLevelStageEvent event){if(event.getStage()!=RenderLevelStageEvent.Stage.AFTER_ENTITIES)return;ensure();drawn=detailDrawn=lodDrawn=0;long start=System.nanoTime();var m=Minecraft.getInstance();if(world==null||!Sk01Config.ENABLED.get())return;var camera=event.getCamera().getPosition();var poses=event.getPoseStack();double lodDistance=Sk01ClientConfig.LOD.get(),distance=Sk01ClientConfig.DISTANCE.get();int max=Sk01ClientConfig.MAX.get();var buffers=m.renderBuffers().bufferSource();
  for(var v:VISIBLE){if(drawn>=max||System.nanoTime()-start>=2_000_000)break;var e=v.entry;if(world.getGameTime()-e.created()<20||!event.getFrustum().isVisible(v.box))continue;double d=e.position().distanceToSqr(camera);if(d>distance*distance||!world.hasChunkAt(BlockPos.containing(e.position())))continue;boolean lod=d>lodDistance*lodDistance;poses.pushPose();poses.translate(e.x()-camera.x,e.y()-camera.y,e.z()-camera.z);poses.mulPose(com.mojang.math.Axis.YP.rotationDegrees(e.yaw()));poses.scale(e.scale(),e.scale(),e.scale());Sk01Model.draw(e,lod,poses,buffers,net.minecraft.client.renderer.LevelRenderer.getLightColor(world,BlockPos.containing(e.position())));poses.popPose();drawn++;if(lod)lodDrawn++;else detailDrawn++;
  }lastRenderNanos=System.nanoTime()-start;
 }
 @SubscribeEvent public static void use(InputEvent.InteractionKeyMappingTriggered event){var m=Minecraft.getInstance();ensure();if(!event.isUseItem()||m.screen!=null||m.player==null||m.level==null||m.getCameraEntity()!=m.player||!m.player.getMainHandItem().is(AddonItems.RS01.get()))return;var eye=m.player.getEyePosition();var end=eye.add(m.player.getLookAngle().scale(6));Visual best=null;double nearest=36;for(var v:VISIBLE){var hit=v.box.clip(eye,end);if(hit.isPresent()&&eye.distanceToSqr(hit.get())<nearest){nearest=eye.distanceToSqr(hit.get());best=v;}}if(best!=null){AddonNetwork.sk01Clear(new Sk01Clear(best.entry.id()));event.setCanceled(true);event.setSwingHand(false);}}
 private Sk01Client(){}
}
